final String svg = "<svg xmlns='http://www.w3.org/2000/svg' width='10' height='10'>"
        + "<circle cx='5' cy='5' r='4' fill='red'/>"
        + "</svg>";
final BufferedImage img = ImageIO.read(new ByteArrayInputStream(svg.getBytes(StandardCharsets.US_ASCII)));

// prints null if there is no reader for SVG
System.out.println(img);
